import { Image } from 'expo-image';
import React from 'react';

type GoogleMarkProps = {
  size?: number;
};

const GOOGLE_G_URI =
  'data:image/svg+xml;base64,';

export function GoogleMark({ size = 20 }: GoogleMarkProps) {
  return (
    <Image
      source={{ uri: GOOGLE_G_URI }}
      style={{ width: size, height: size }}
      contentFit="contain"
    />
  );
}
